import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import os
import subprocess
import pathlib as _pl

import pytest

from hatalar import BarkodHatasi, AdetHatasi
from stok import StokYoneticisi

WORKDIR = _pl.Path(__file__).resolve().parent.parent


def _barkod_al(item):
    if isinstance(item, (list, tuple)) and len(item) >= 2:
        return str(item[0])
    if isinstance(item, dict):
        for k in ("barkod", "barcode", "kod"):
            if k in item:
                return str(item[k])
        if len(item) == 1:
            return str(next(iter(item.keys())))
    return str(item).split()[0] if str(item).split() else str(item)


def _adet_al(item):
    if isinstance(item, (list, tuple)) and len(item) >= 2:
        return int(item[1])
    if isinstance(item, dict):
        for k in ("adet", "miktar", "count", "quantity"):
            if k in item:
                return int(item[k])
        if len(item) == 1:
            return int(next(iter(item.values())))
    parts = str(item).split()
    for p in parts[1:]:
        try:
            return int(p)
        except ValueError:
            continue
    return None


def _run_cli(args, tmp_path):
    env = os.environ.copy()
    env["STOK_DOSYASI"] = str(tmp_path / "stok.json")
    return subprocess.run(
        [sys.executable, "-m", "stok"] + args,
        cwd=str(WORKDIR),
        env=env,
        capture_output=True,
        text=True,
        timeout=15,
    )


