    _run_cli(["ekle", "--barkod", "22222222", "--adet", "4"], tmp_path)
    r = _run_cli(["rapor"], tmp_path)
    assert r.returncode == 0
    satirlar = [s for s in r.stdout.strip().splitlines() if s.strip()]
    assert len(satirlar) >= 2
    birlesik = "\n".join(satirlar)
    assert "11111111" in birlesik and "3" in birlesik
    assert "22222222" in birlesik and "4" in birlesik
    for s in satirlar:
        if "11111111" in s:
            assert "3" in s
        if "22222222" in s:
            assert "4" in s

